/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Common class for customer and vendor external data
/// </summary>
public class METTAMRebateQueryBuilderExternalData extends TAMRebateQueryBuilder
{
}

Method.Source:
public FieldId dateFieldId()
{
    return fieldNum(METRebateScanSupplierTable, TransactionDate);
}

protected FieldId inventTransIdFieldId()
{
    return fieldNum(METRebateScanSupplierTable, TransactionNumber);
}

public FieldId itemFieldId()
{
    return fieldNum(METRebateScanSupplierTable, ItemId);
}

public FieldId inventDimIdFieldId()
{
    // Not used, can keep this here as we don't have InventDimId in METRebateScanSupplierTable
    return 0;
}

public TableId journalTable()
{
    // same as transTable()
    return tableNum(METRebateScanSupplierTable);
}

public FieldId transTableRecIdFieldId()
{
    return fieldNum(METRebateScanSupplierTable, RecId);
}

/// <summary>
/// pending MS extensibility request
/// </summary>
/// <returns><c>Query</c></returns>
public Query buildBaseQuery()
{
    query = new Query();

    //QueryBuildDataSource qbds = query.addDataSource(this.journalTable());
    QueryBuildDataSource qbds = query.addDataSource(this.transTable());

    QueryBuildRange qbr = qbds.addRange(this.accountJourTableFieldId());
    qbr.status(RangeStatus::Locked);

    /*qbds = qbds.addDataSource(this.transTable());
    qbds.relations(true);
    qbds.fetchMode(QueryFetchMode::One2One);*/

    qbr = qbds.addRange(this.itemFieldId());
    qbr.status(RangeStatus::Locked);

    qbr = qbds.addRange(this.dateFieldId());
    qbr.status(RangeStatus::Locked);

    return query;
}
